def build_curated_raw_dataset():
    """Builds and saves the verified historical movie dataset."""
    all_movies = VERIFIED_HISTORICAL_MOVIES + ADDITIONAL_REAL_MOVIES
    df = pd.DataFrame(all_movies)
    
    # Ensure correct data types
    df['id'] = df['id'].astype(int)
    df['budget'] = df['budget'].astype(float)
    df['revenue'] = df['revenue'].astype(float)
    df['runtime'] = df['runtime'].astype(float)
    df['is_franchise'] = df['is_franchise'].astype(int)
    df['release_date'] = pd.to_datetime(df['release_date'])
    df['data_source'] = 'VERIFIED_HISTORICAL_TMDB'
    df['is_synthetic'] = 0
    
    # Sort chronologically by release date
    df = df.sort_values('release_date').reset_index(drop=True)
    
    output_path = os.path.join(RAW_DIR, "tmdb_movies_curated.csv")
    df.to_csv(output_path, index=False)
    print(f"[Dataset] Wrote {len(df)} verified historical movie records to {output_path}")
    return df

def build_synthetic_dev_dataset():
    """
    Builds a small, clearly labelled synthetic dataset solely for offline pipeline testing and CI.
    Tagged with data_source='SYNTHETIC_DEV' and is_synthetic=1.
    """
    np.random.seed(42)
    genres_pool = ["Action", "Comedy", "Drama", "Sci-Fi", "Horror", "Romance", "Adventure", "Thriller", "Animation"]
    studios_pool = ["Apex Studios", "Nebula Pictures", "Starlight Media", "Vanguard Entertainment", "Nova Films"]
    
    synthetic_records = []
    start_date = pd.to_datetime("2020-01-01")
    
    for i in range(1, 41):
        g_count = np.random.choice([1, 2, 3])
        genres = ", ".join(np.random.choice(genres_pool, size=g_count, replace=False))
        studio = np.random.choice(studios_pool)
        
        # Realistic synthetic distributions
        budget = float(np.random.choice([
            np.random.uniform(5000000, 25000000),   # Low-mid budget
            np.random.uniform(30000000, 80000000),  # Mid budget
            np.random.uniform(90000000, 220000000)  # Tentpole
        ]))
        
        # Synthetic revenue with realistic ROI multiplier
        multiplier = np.random.lognormal(mean=0.8, sigma=0.6)
        revenue = float(budget * multiplier)
        runtime = float(np.random.randint(85, 165))
        is_franchise = int(np.random.choice([0, 1], p=[0.7, 0.3]))
        rel_days = np.random.randint(0, 1500)
        rel_date = (start_date + pd.Timedelta(days=rel_days)).strftime("%Y-%m-%d")
        
        synthetic_records.append({
            "id": 90000 + i,
            "title": f"Synthetic Film {i}: Project {chr(65 + (i % 26))}",
            "budget": round(budget, 2),
            "revenue": round(revenue, 2),
            "genres": genres,
            "release_date": rel_date,
            "runtime": runtime,
            "original_language": "en",
            "production_companies": studio,
            "is_franchise": is_franchise,
            "overview": f"A synthetic development record designed strictly for integration testing of project {i}.",
            "data_source": "SYNTHETIC_DEV",
            "is_synthetic": 1
        })
        
    df_synth = pd.DataFrame(synthetic_records)
    output_path = os.path.join(SYNTH_DIR, "synthetic_movies_dev.csv")
    df_synth.to_csv(output_path, index=False)
    print(f"[Dataset] Wrote {len(df_synth)} synthetic development records to {output_path}")
    return df_synth

if __name__ == "__main__":
    build_curated_raw_dataset()
    build_synthetic_dev_dataset()
